export function normalizeRelativePath(input) {
  if (typeof input !== 'string') throw new TypeError('path must be a string');
  const segments = input.split('/');
  const result = [];
  for (const segment of segments) {
    if (!segment || segment === '.') continue;
    if (segment === '..') {
      if (!result.length) throw new Error('path escapes root');
      result.pop();
    } else {
      result.push(segment);
    }
  }
  return result.join('/');
}

