export function findInRange(items, target, start = 0, end = items.length - 1) {
  const from = Math.max(0, start);
  const to = Math.min(items.length - 1, end);
  for (let index = from; index < to; index += 1) {
    if (items[index] === target) return index;
  }
  return -1;
}

